app.MapGet("/login",()=>Results.Content("""<!doctype html><html lang=ru><head><meta charset=utf-8><meta name=viewport content="width=device-width"><title>Вход · Finance Analytics</title><style>body{margin:0;background:#f1f4f9;font:15px Arial;color:#18243e;display:grid;place-items:center;min-height:100vh}.card{width:min(390px,calc(100% - 40px));background:#fff;padding:34px;border-radius:18px;box-shadow:0 18px 55px #18243e20}h1{margin:0 0 8px}.muted{color:#718096;margin-bottom:24px}label{display:block;margin:14px 0 6px;font-weight:600}input{box-sizing:border-box;width:100%;padding:12px;border:1px solid #d9deea;border-radius:9px;font-size:16px}button{width:100%;margin-top:22px;padding:13px;border:0;border-radius:9px;background:#465be8;color:white;font-weight:700}</style></head><body><form method=post class=card><h1>Finance Analytics</h1><div class=muted>Промежуточные итоги и диаграммы</div><label>Логин</label><input name=username required autofocus><label>Пароль</label><input name=password type=password required><button>Войти</button></form></body></html>""","text/html")).AllowAnonymous();
app.MapPost("/login",async(HttpContext c,IConfiguration cfg)=>{var f=await c.Request.ReadFormAsync();if(f["username"]!=(cfg["AnalyticsAuth:Username"]??"admin")||f["password"]!=(cfg["AnalyticsAuth:Password"]??""))return Results.Content("Неверный логин или пароль","text/plain",statusCode:401);var id=new ClaimsIdentity([new Claim(ClaimTypes.Name,f["username"]!)],CookieAuthenticationDefaults.AuthenticationScheme);await c.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(id));return Results.Redirect("/");}).AllowAnonymous();
app.MapGet("/",async(FinanceDbContext db,string? company,int? year,int? month)=>{
 var companies=await db.Companies.AsNoTracking().OrderBy(x=>x.Kind).ToListAsync();var requestedKind=string.Equals(company,"orient",StringComparison.OrdinalIgnoreCase)?CompanyKind.Broker:CompanyKind.LiquidityProvider;var selected=companies.FirstOrDefault(x=>x.Kind==requestedKind)??companies.First();var companyKey=selected.Kind==CompanyKind.Broker?"orient":"liquidity";var now=DateTimeOffset.UtcNow;var y=year is >=2000 and <=2100?year.Value:now.Year;var m=month is >=1 and <=12?month:null;var from=new DateTimeOffset(y,m??1,1,0,0,0,TimeSpan.Zero);var to=m.HasValue?from.AddMonths(1):from.AddYears(1);var report=await new MonthlyReportHandler(db).Handle(new MonthlyReportQuery(selected.Id,from,to),default);var ru=CultureInfo.GetCultureInfo("ru-RU");var period=m.HasValue?from.ToString("MMMM yyyy",ru):y.ToString();
 string E(object? value)=>HtmlEncoder.Default.Encode(value?.ToString()??"");string N(decimal value)=>value.ToString("N2",ru);
 var operations=new StringBuilder();foreach(var x in report.Operations)operations.Append($"<tr><td>{E(OperationTypes.All.GetValueOrDefault(x.TypeCode,x.TypeCode))}</td><td>{x.Count}</td><td>{N(x.BuyAmount)} {E(x.BuyCurrency)}</td><td>{N(x.SellAmount)} {E(x.SellCurrency)}</td><td class=neg>{N(x.Expenses)}</td><td class='{(x.Profit<0?"neg":"pos")}'>{N(x.Profit)}</td></tr>");if(report.Operations.Count==0)operations.Append("<tr><td colspan=6 class=empty>За выбранный период операций нет</td></tr>");
 var flows=new StringBuilder();foreach(var x in report.Flows)flows.Append($"<tr><td><b class=currency>{E(x.Currency)}</b></td><td>{N(x.Incoming)}</td><td>{N(x.Outgoing)}</td><td class='{(x.Net<0?"neg":"pos")}'>{N(x.Net)}</td><td class='{(x.ProfitUsd<0?"neg":"pos")}'>{N(x.ProfitUsd)}</td></tr>");
 var balances=new StringBuilder();foreach(var x in report.Balances)balances.Append($"<tr><td><b class=currency>{E(x.Currency)}</b></td><td>{N(x.Opening)}</td><td>{N(x.Closing)}</td><td>{N(x.OpeningUsdt)}</td><td><b>{N(x.ClosingUsdt)}</b></td></tr>");
 var sidebar=$"<div class='nav-title'>Компании</div><a class='nav {(companyKey=="orient"?"active":"")}' href='/?company=orient&amp;year={y}{(m.HasValue?$"&amp;month={m}":"")}'>Orient Capital</a><a class='nav {(companyKey=="liquidity"?"active":"")}' href='/?company=liquidity&amp;year={y}{(m.HasValue?$"&amp;month={m}":"")}'>A&amp;A Ликвидность</a>";var monthOptions="<option value=''>Весь год</option>"+string.Join("",Enumerable.Range(1,12).Select(x=>$"<option value='{x}' {(m==x?"selected":"")}>{ru.DateTimeFormat.GetMonthName(x)}</option>"));
 var opLabels=JsonSerializer.Serialize(report.Operations.Select(x=>OperationTypes.All.GetValueOrDefault(x.TypeCode,x.TypeCode)));var opProfits=JsonSerializer.Serialize(report.Operations.Select(x=>x.Profit));var flowLabels=JsonSerializer.Serialize(report.Flows.Select(x=>x.Currency));var incoming=JsonSerializer.Serialize(report.Flows.Select(x=>x.Incoming));var outgoing=JsonSerializer.Serialize(report.Flows.Select(x=>x.Outgoing));var balLabels=JsonSerializer.Serialize(report.Balances.Select(x=>x.Currency));var opening=JsonSerializer.Serialize(report.Balances.Select(x=>x.OpeningUsdt));var closing=JsonSerializer.Serialize(report.Balances.Select(x=>x.ClosingUsdt));
 var html="""<!doctype html><html lang=ru><head><meta charset=utf-8><meta name=viewport content="width=device-width"><title>Промежуточный итог · Finance Analytics</title><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script><style>:root{--nav:#111d3f;--primary:#4f46e5;--bg:#f4f6fa;--line:#e5e9f2}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#17213a;font:14px Arial}.shell{display:grid;grid-template-columns:245px 1fr;min-height:100vh}aside{background:var(--nav);color:#fff;padding:26px 20px}.brand{font-size:22px;font-weight:800;margin-bottom:35px}.nav-title{margin:0 12px 10px;color:#92a0c4;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em}.nav{display:block;padding:13px 12px;border-radius:9px;color:#dce3f7;text-decoration:none;margin:7px 0;border:1px solid transparent}.nav:hover{background:#ffffff12}.nav.active{background:#4f46e5;color:#fff;border-color:#7770f0;font-weight:700}.content{padding:28px;max-width:1500px;width:100%}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}h1{margin:0 0 5px}.muted{color:#748097}.period{background:#e8e7ff;color:#4338ca;padding:8px 13px;border-radius:20px;font-weight:700}.filter,.card,.metric{background:#fff;border:1px solid var(--line);border-radius:13px;box-shadow:0 3px 14px #17213a08}.filter{padding:17px;display:grid;grid-template-columns:1fr 1.5fr 1fr;gap:12px;margin-bottom:18px}label{display:block;font-size:12px;font-weight:700;margin-bottom:6px}select,input,button{width:100%;height:39px;border:1px solid #d7dce8;border-radius:8px;padding:0 10px;background:#fff}button{background:var(--primary);color:#fff;border:0;font-weight:700;margin-top:18px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.metric{padding:19px}.metric span{display:block;color:#748097}.metric strong{display:block;font-size:24px;margin-top:7px}.charts{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin-bottom:18px}.card{margin-bottom:18px;overflow:hidden}.card h2{font-size:16px;margin:0;padding:17px;border-bottom:1px solid var(--line)}.chart{height:310px;padding:16px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px 14px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{font-size:12px;color:#667085;background:#fafbfc}.pos{color:#16875b;font-weight:700}.neg{color:#dc3545;font-weight:700}.currency{background:#edf0ff;color:#4338ca;padding:5px 8px;border-radius:6px}.empty{text-align:center!important;color:#748097;padding:30px}@media(max-width:900px){.shell{grid-template-columns:1fr}aside{padding:18px}.brand{margin-bottom:18px}.content{padding:16px}.filter,.metrics,.charts{grid-template-columns:1fr}}</style></head><body><div class=shell><aside><div class=brand>Finance Analytics</div>__SIDEBAR__</aside><main class=content><header><div><h1>Промежуточный итог</h1><div class=muted>__COMPANY__ · те же данные и расчёты, что в основном приложении</div></div><span class=period>__PERIOD__</span></header><form class=filter><input type=hidden name=company value=__COMPANY_KEY__><div><label>Год</label><input name=year type=number value=__YEAR__></div><div><label>Месяц</label><select name=month>__MONTHS__</select></div><div><button>Сформировать</button></div></form><div class=metrics><div class=metric><span>Прибыль по операциям</span><strong>__PROFIT__ USDT</strong></div><div class=metric><span>Расходы</span><strong class=neg>__EXPENSES__ USDT</strong></div><div class=metric><span>Финансовый результат</span><strong>__NET__ USDT</strong></div></div><div class=charts><div class=card><h2>Прибыль по типам операций</h2><div class=chart><canvas id=profitChart></canvas></div></div><div class=card><h2>Приход и расход по валютам</h2><div class=chart><canvas id=flowChart></canvas></div></div><div class=card><h2>Сальдо в USDT</h2><div class=chart><canvas id=balanceChart></canvas></div></div><div class=card><h2>Структура результата</h2><div class=chart><canvas id=pieChart></canvas></div></div></div><div class=card><h2>Итоги покупки и продажи</h2><div class=scroll><table><thead><tr><th>Операция</th><th>Сделок</th><th>Получили</th><th>Отдали</th><th>Расходы, USDT</th><th>Прибыль, USDT</th></tr></thead><tbody>__OPERATIONS__</tbody></table></div></div><div class=card><h2>Движение по валютам</h2><div class=scroll><table><thead><tr><th>Валюта</th><th>Приход</th><th>Расход</th><th>Разница</th><th>Прибыль, USDT</th></tr></thead><tbody>__FLOWS__</tbody></table></div></div><div class=card><h2>Сальдо</h2><div class=scroll><table><thead><tr><th>Валюта</th><th>На начало</th><th>На конец</th><th>На начало, USDT</th><th>На конец, USDT</th></tr></thead><tbody>__BALANCES__</tbody></table></div></div></main></div><script>const opLabels=__OPLABELS__,opProfits=__OPPROFITS__,flowLabels=__FLOWLABELS__,incoming=__INCOMING__,outgoing=__OUTGOING__,balLabels=__BALLABELS__,opening=__OPENING__,closing=__CLOSING__;new Chart(profitChart,{type:'bar',data:{labels:opLabels,datasets:[{data:opProfits,backgroundColor:opProfits.map(x=>x<0?'#ef4444':'#4f46e5'),borderRadius:6}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}}}});new Chart(flowChart,{type:'bar',data:{labels:flowLabels,datasets:[{label:'Приход',data:incoming,backgroundColor:'#10b981'},{label:'Расход',data:outgoing,backgroundColor:'#f59e0b'}]},options:{maintainAspectRatio:false}});new Chart(balanceChart,{type:'bar',data:{labels:balLabels,datasets:[{label:'На начало',data:opening},{label:'На конец',data:closing}]},options:{maintainAspectRatio:false}});new Chart(pieChart,{type:'doughnut',data:{labels:flowLabels,datasets:[{data:incoming,backgroundColor:['#4f46e5','#10b981','#f59e0b','#ef4444','#06b6d4','#8b5cf6']}]},options:{maintainAspectRatio:false}});</script></body></html>""";
 html=html.Replace("__SIDEBAR__",sidebar).Replace("__COMPANY__",E(selected.Name)).Replace("__COMPANY_KEY__",companyKey).Replace("__PERIOD__",E(period)).Replace("__YEAR__",y.ToString()).Replace("__MONTHS__",monthOptions).Replace("__PROFIT__",N(report.Profit)).Replace("__EXPENSES__",N(report.Expenses)).Replace("__NET__",N(report.NetProfit)).Replace("__OPERATIONS__",operations.ToString()).Replace("__FLOWS__",flows.ToString()).Replace("__BALANCES__",balances.ToString()).Replace("__OPLABELS__",opLabels).Replace("__OPPROFITS__",opProfits).Replace("__FLOWLABELS__",flowLabels).Replace("__INCOMING__",incoming).Replace("__OUTGOING__",outgoing).Replace("__BALLABELS__",balLabels).Replace("__OPENING__",opening).Replace("__CLOSING__",closing);return Results.Content(html,"text/html");
